// Generated by nexo-ai. Do not edit: change hooks.yaml and run `nexo-ai install opencode`.
//
// OpenCode has no command hooks. This shim hands each event to the nexo-ai binary, which
// runs the matching hooks with a Claude-shaped payload and answers whether to block.
// If the binary is missing or fails, the event goes through (fail open).
import { spawn } from "node:child_process"

const NEXO = __NEXO_BIN__
const HOOKS_FILE = __NEXO_HOOKS_FILE__

let warned = false

function dispatch(request) {
  return new Promise((resolve) => {
    const child = spawn(NEXO, ["hook", "opencode", "--hooks", HOOKS_FILE], { stdio: ["pipe", "pipe", "ignore"] })
    let out = ""
    child.stdout.on("data", (chunk) => (out += chunk))
    // A binary that exits before reading stdin makes the write fail (EPIPE): ignore it,
    // the event goes through.
    child.stdin.on("error", () => {})
    child.on("error", (error) => {
      if (!warned) {
        warned = true
        console.error(`nexo-ai hooks are not running: cannot start ${NEXO} (${error.message}); run nexo-ai install opencode again`)
      }
      resolve({})
    })
    child.on("close", () => {
      try { resolve(JSON.parse(out || "{}")) } catch { resolve({}) }
    })
    child.stdin.end(JSON.stringify(request))
  })
}

async function run(request) {
  const result = await dispatch(request)
  if (result.block) throw new Error(result.block)
}

export const NexoHooks = async ({ directory }) => {
  const argsByCall = new Map()
  return {
    "tool.execute.before": async (input, output) => {
      argsByCall.set(input.callID, output.args)
      await run({ hook: "tool.execute.before", tool: input.tool, sessionID: input.sessionID, args: output.args, directory })
    },
    "tool.execute.after": async (input) => {
      const args = argsByCall.get(input.callID)
      argsByCall.delete(input.callID)
      await run({ hook: "tool.execute.after", tool: input.tool, sessionID: input.sessionID, args, directory })
    },
    "chat.message": async (input, output) => {
      const prompt = (output.parts || []).filter((p) => p.type === "text").map((p) => p.text).join("\n")
      await run({ hook: "chat.message", sessionID: input.sessionID, prompt, directory })
    },
    event: async ({ event }) => {
      const props = event.properties || {}
      if (event.type === "session.created") await run({ hook: "session.created", sessionID: props.info && props.info.id, directory })
      if (event.type === "session.idle") await run({ hook: "session.idle", sessionID: props.sessionID, directory })
    },
  }
}
